namespace Superiorly.PostInstall.Services;

public static partial class TranslationService
{
    private static readonly Dictionary<string, string> ActionInfo_pl = new()
    {

            ["process-explorer"]="Zaawansowany menedżer zadań pokazujący użycie uchwytów/DLL w czasie rzeczywistym, drzewa procesów, pamięć GPU i weryfikację podpisów kodu. Rozwiązuje symbole stosu wątków i pokazuje I/O na proces. Narzędzie diagnostyczne tylko do odczytu.",
            ["nsudo"]="Uruchamia procesy jako TrustedInstaller, SYSTEM lub z pełnymi uprawnieniami. Niezbędne do modyfikacji chronionych plików lub przejmowania zablokowanych zasobów. Ostrzeżenie: omija wszystkie kontrole bezpieczeństwa.",
            ["driverview"]="Wyświetla wszystkie sterowniki trybu jądra z wersją, typem i użyciem pamięci. Wykrywa niepodpisane lub przestarzałe sterowniki powodujące BSOD. Przydatne do diagnozy konfliktów sterowników.",
            ["cru"]="Dodaje niestandardowe rozdzielczości, częstotliwości odświeżania i parametry czasowe poprzez nadpisania EDID w rejestrze. Uruchom ponownie sterownik, aby zastosować bez restartu. Ostrzeżenie: błędne wartości mogą powodować brak sygnału.",
            ["windows-update-manager"]="Szczegółowa kontrola Windows Update: ukrywanie/pokazywanie aktualizacji, odraczanie aktualizacji jakości, zarządzanie sterownikami i wstrzymanie wszystkich. Unikaj problematycznych aktualizacji, zachowując aktualne poprawki zabezpieczeń.",
            ["mousetester"]="Analizuje stabilność próbkowania myszy, stabilność wejścia i wydajność sensora. Rejestruje surowe dane ruchu i rysuje prędkość, jitter oraz korekcję kąta. Tryb podwójny mierzy opóźnienie wejścia między dwiema myszami.",
            ["geek-uninstaller"]="Przenośny wymuszony deinstalator upartych programów Windows, aplikacji Store i rozszerzeń. Skanuje rejestr i system plików po odinstalowaniu. Nie wymaga instalacji.",
            ["measuresleep"]="Mierzy precyzję Sleep() systemu Windows, porównując rzeczywiste i żądane interwały. Wykrywa problemy rozdzielczości timera powodujące mikroprzycięcia i opóźnienia wejścia. Użyj z SetTimerResolution, aby zweryfikować poprawę.",
            ["ocat"]="Nakładka FPS i przechwytywanie czasów klatek dla D3D11, D3D12 i Vulkan. Używa Intel PresentMon dla dokładnego pomiaru. Nagrywa ślady czasów klatek skrótem. Działa z każdym GPU.",
            ["onboard-memory-manager"]="Konfiguruje DPI, przyciski i podświetlenie w pamięci wbudowanej myszy Logitech G. Eliminuje potrzebę działania G HUB w tle. Obsługuje Pro X Superlight, G Pro, G502, G305 i inne serie G.",
            ["performance-measurement"]="Podnosi przerwanie zegara Windows do 0,5 ms przez NtSetTimerResolution, zmniejszając opóźnienia wejścia i poprawiając płynność klatek. Zamknij aplikację, aby przywrócić domyślny timer. Niezbędne w grach rywalizacyjnych i produkcji audio.",
            ["autoruns"]="Pokazuje wszystkie autostartujące programy, usługi, sterowniki i zaplanowane zadania. Bezpiecznie wyłącz znane zbędne wpisy. Użyj Ukryj wpisy Microsoft, aby skupić się na innych. Ryzyko: wyłączenie Winlogon/usług uniemożliwia start.",
            ["devicecleanup"]="Usuwa wpisy rejestru odłączonego sprzętu. Bezpieczne tylko dla nieobecnych urządzeń. Podobne do DevNodeClean firmy Microsoft. Ryzyko minimalne.",
            ["gointerruptpolicy"]="Ustawia powinowactwo CPU i priorytety procesów. Przydatne do przypinania silników gier do określonych rdzeni. Ryzyko: błędne powinowactwo obniża wydajność.",
            ["serviwin"]="Wyświetla usługi i sterowniki Windows ze statusem. Bezpiecznie zatrzymaj/wyłącz znane zbędne usługi. Ryzyko: wyłączenie krytycznych usług (RPC, DCOM) uszkadza system.",
            ["usbtreeview"]="Pokazuje drzewo urządzeń USB ze stanem zasilania i przepustowością. Przydatne do debugowania USB. Tylko do odczytu.",
            ["ddu"]="Usuwa wszystkie pozostałości sterowników GPU (pliki, rejestr, foldery) pomijane przez standardowe deinstalatory. Użyj przy zmianie marki GPU lub naprawie uszkodzonych sterowników. Uruchom w trybie awaryjnym dla najlepszych wyników.",
            ["filterkeysetter"]="Dostosowuje wartości Windows FilterKeys poza limity Panelu sterowania: opóźnienie i szybkość powtarzania, opóźnienie akceptacji i czas odbicia. Wpływa na edytory i aplikacje używające wysokopoziomowego wejścia klawiatury. Nowoczesne gry używające DirectInput lub Raw Input nie są dotknięte.",
            ["brave-debloat"]="Stosuje 12 zasad Brave. Wymaga Brave 1.82+ (Playlist 1.84+). Uruchom ponownie; wyświetla jako zarządzane.",
            ["edge-debloat"]="Stosuje 14 zasad Edge . Uruchom ponownie; wyświetla jako zarządzane.",
            ["throttlestop"]="Obniża napięcie CPU przez FIVR, steruje turbo boost (PL1/PL2), przełącza BD PROCHOT i zarządza Speed Shift/EPP. Obniża temperatury i zapobiega throttlingowi termicznemu. Wymaga admina.",
            ["radeonsoftwareslimmer"]="Usuwa zbędne składniki AMD Radeon Software (telemetria, procesy w tle). Oszczędza 200-400 MB RAM. Bezpieczne dla wszystkich GPU AMD.",
            ["moreclocktool"]="Szczegółowa kontrola taktowania GPU AMD, krzywych napięć i stanów zasilania. Niezbędne dla Polaris, Vega i RDNA1. Ostrzeżenie: błędne napięcie powoduje niestabilność GPU.",
            ["morepowertool"]="Modyfikuje tabele zasilania GPU AMD, nadpisując limity, krzywe wentylatorów i throttling na poziomie sterownika. Obsługuje Polaris, Vega, RDNA1/2/3. Ostrzeżenie: może trwale uszkodzić sprzęt.",
            ["radeonmod"]="Edytuje ukryte wartości rejestru sterownika AMD: Flip Queue Size, pamięć podręczną shaderów, ULPS, potrójne buforowanie, teselację. Obsługuje Radeon HD 5000 do RX 500. Zawsze najpierw wykonaj kopię rejestru.",
            ["nvcleanstall"]="Okraja sterowniki NVIDIA do niezbędnych. Usuwa telemetrię, GeForce Experience, audio HDMI. Oszczędza ponad 500 MB dysku i usuwa usługi w tle. Instaluje tylko podstawowy sterownik ekranu i PhysX.",
            ["nvidia-inspector"]="Monitorowanie GPU w czasie rzeczywistym: taktowania, napięcia, temperatury, wentylatory, pobór mocy. Odczytuje czujniki na poziomie sprzętu. Przydatne do weryfikacji stabilności overclockingu i throttlingu.",
            ["apply-nip"]="Wstępnie skonfigurowane nadpisania profili sterownika dla gier. Optymalizuje AA, AF, jakość tekstur i zasilanie na tytuł. Profile zależą od wersji sterownika NVIDIA.",
            ["force-pstate0"]="Blokuje GPU NVIDIA w maksymalnym stanie (P0), zapobiegając skalowaniu zegarów powodującemu nierówne czasy klatek. Ostrzeżenie: zwiększa pobór w spoczynku o 20-40 W i temperatury. Wyłącz poza grą.",
            ["lazymodetimeout"]="Limit leniwego cyklu wykrywania bezczynności MMCSS. Domyślnie: 1 000 000 (100 ms). Niższy = szybsze wybudzanie, lecz częstsze wybudzenia CPU. Ukryte nieudokumentowane ustawienie.",
            ["systemresponsiveness"]="Rezerwa MMCSS dla zadań w tle (0-100, domyślnie 20). Wartości 0-9 przycięte do 20. 10-100 zaokrąglone w dół do dziesiątek. 100 wyłącza MMCSS.",
            ["receive-buffers"]="Rozmiar bufora odbiorczego karty sieciowej. Wyższy może poprawić przepustowość. Ryzyko: używa więcej pamięci.",
            ["transmit-buffers"]="Rozmiar bufora nadawczego karty sieciowej. Wyższy może poprawić przepustowość. Ryzyko: używa więcej pamięci.",
            ["csrss-priority"]="Priorytet środowiska CSRSS. Modyfikacja może wpłynąć na responsywność. Ryzyko: błędne wartości powodują opóźnienia UI.",
            ["iolatencycap"]="Limit opóźnienia I/O w ms. Niższy = szybsze I/O. Ryzyko: zbyt niski może powodować błędy I/O.",
            ["iopagelocklimit"]="Limit zablokowanych stron I/O w bajtach. Kontroluje pamięć zablokowaną dla I/O. Ryzyko: błędne wartości powodują niestabilność.",
            ["nagle-algorithm"]="Algorytm Nagle grupuje małe pakiety TCP. Wyłączenie zmniejsza opóźnienia aplikacji czasu rzeczywistego. Ryzyko: może zwiększyć narzut sieci.",
            ["nolazymode"]="Wyłącza leniwy tryb NoLazyMode wykrywania bezczynności MMCSS. Wątki zachowują podwyższony priorytet. Może zwiększyć zużycie CPU. Ukryte nieudokumentowane ustawienie.",
            ["tsc-sync-policy"]="Polityka synchronizacji TSC między rdzeniami. Ryzyko: może wpływać na aplikacje wrażliwe na czas.",
            ["useplatformtick"]="Wymusza tick platformy zamiast HPET. Może zmniejszyć opóźnienia timera. Ryzyko: część sprzętu go nie obsługuje.",
            ["disable-mpo"]="Wyłącza Multi-Plane Overlay MPO. Może naprawić przycięcia w niektórych grach. Ryzyko: może zwiększyć użycie GPU w trybie okna.",
            ["disable-interrupt-steering"]="Wyłącza kierowanie przerwań. Przerwania zostają na pierwszym rdzeniu. Ryzyko: może zwiększyć opóźnienia pierwszego rdzenia.",
            ["disable-power-throttling"]="Wyłącza ograniczanie zasilania Windows. Zapewnia stały zegar CPU. Ryzyko: większe zużycie na laptopach.",
            ["threaded-dpc"]="Włącza wątkowe przetwarzanie DPC. Może zmniejszyć skoki opóźnień DPC. Ryzyko minimalne na nowoczesnym sprzęcie.",
            ["cpu-idle"]="Kontroluje stan bezczynności CPU (C-states). Niższy = głębszy sen (oszczędność). Wyższy = CPU gotowy (mniejsze opóźnienia).",
            ["force-direct-flip"]="Wymusza Direct Flip dla pełnego ekranu. Omija DWM. Ryzyko: może wpływać na programy do przechwytywania.",
            ["force-independent-flip"]="Wymusza niezależny flip dla pełnego ekranu. Zmniejsza narzut DWM. Ryzyko: problemy z wieloma monitorami.",
            ["force-flip-true-immediate"]="Wymusza natychmiastowy czas flip. Zmniejsza opóźnienia klatek. Ryzyko: może powodować tearing.",
            ["disablepagingexecutive"]="Trzyma sterowniki jądra w RAM. Zmniejsza I/O dysku. Ryzyko: używa więcej RAM.",
            ["disablepagecombining"]="Wyłącza łączenie stron (deduplikację pamięci). Ryzyko: nieznacznie większe użycie pamięci.",
            ["queued-present-limit"]="Kontroluje kolejkowane klatki dla DWM. Mniej = mniejsze opóźnienia wejścia, lecz potencjalnie niższe FPS.",
            ["win32priorityseparation"]="Strategia kwantu CPU przez PriorityControl. Domyślnie 2 (krótki/zmienny/boost 3:1). 0x26=boost 2:1. 0x18=długi/stały/bez boost (styl serwera).",
            ["vbs"]="Izoluje krytyczne procesy OS od jądra przy użyciu wirtualizacji sprzętowej. Włącza KDP i Credential Guard. Narzut: 1-5% przy obciążeniach I/O. Wyłącz tylko dla zgodności Hyper-V innych firm.",
            ["hvci"]="Uruchamia kontrole integralności kodu jądra w hipernadzorcy VBS, blokując niepodpisane/podatne sterowniki. Blokuje ataki BYOVD. Wpływ: 2-5% na I/O sterowników. Wyłącz tylko przy BSOD lub konfliktach z anti-cheat.",
            ["firewall"]="Stanowa inspekcja pakietów i filtrowanie na poziomie aplikacji. BFE wymagane dla IPsec, WFP i VPN. Narzut: <0,1% CPU. Wyłączenie naraża SMB, RDP na ruch boczny. Zawsze pozostaw włączone.",
            ["lua"]="Oddziela standardowe i podwyższone konteksty tokenów dla najmniejszych uprawnień. Wyłączenie pozwala każdemu procesowi pisać do katalogów systemowych. Pozostaw włączone.",
            ["vulnerable-driver-blocklist"]="Blokuje przy starcie znane wykorzystywane sterowniki jądra przez HVCI + CI. Przeciw atakom BYOVD. Zerowy koszt w runtime. Zawsze włącz, chyba że wymagany sterownik legacy.",
            ["nx-mode"]="Kontroluje sprzętowe zapobieganie wykonywaniu danych (DEP). OptIn (domyślnie): tylko procesy systemowe. OptOut: wszystkie procesy. AlwaysOn: najbezpieczniejsze, lecz może psuć starsze aplikacje. Znikomy narzut CPU.",
            ["show-tray-icons"]="Ustawienie Exploratora dla użytkownika. Ignorowane w Windows 11 22H2+, gdzie stan ikon przeniesiono do NotifyIconSettings. Działa po restarcie Eksploratora.",
            ["menus-delay"]="Wartości tekstowe dla użytkownika. Działa natychmiast.",
            ["network-throttling"]="Działa tylko w trakcie wykonywania zadania MMCSS. Wyłączenie zeruje także rezerwację QoS. Pomaga przy transferach o dużej przepustowości, nie przy opóźnieniu (ping).",
            ["error-reporting"]="Zatrzymuje WerSvc (fabrycznie Ręczny) i wercplsupport. Raporty awarii przestają trafiać do Microsoft. Wymagany restart.",
            ["compat-assistant"]="Zatrzymuje sprawdzanie zgodności w tle. Wymagany restart.",
            ["sticky-keys"]="Gałęzie użytkownika i domyślnego użytkownika. Kończy monity Shift x5. Restart nie jest wymagany.",
            ["smb1"]="Przestarzały i niebezpieczny (WannaCry). Pozostaw wyłączony, chyba że wymagają go bardzo stare udziały NAS. Wymagany restart.",
            ["smb2"]="UWAGA: wyłączenie psuje nowoczesne udostępnianie plików, drukarki i dostęp do domeny. Tylko do odizolowanych testów starszych mechanizmów. Wymagany restart.",
            ["ntfs-timestamp"]="Wyłączenie oszczędza niewielką liczbę zapisów na SSD. Brak wskaźnika stanu (sprawdzanie nieobsługiwane). Efekt natychmiastowy.",
            ["system-restore"]="UWAGA: wyłączenie nieodwracalnie usuwa istniejące kopie w cieniu. Wymagany restart.",
            ["superfetch"]="Na dyskach SSD Windows dostosowuje się automatycznie; wyłączenie może spowolnić uruchamianie aplikacji. Wyłącz tylko wtedy, gdy SysMain działa nieprawidłowo. Wymagany restart.",
            ["homegroup"]="HomeGroup usunięto w Windows 10 1803 i nowszych; bezpiecznie wyłączyć. Wymagany restart.",
            ["media-sharing"]="Potrzebne tylko do strumieniowania DLNA. Włączenie przywraca tryb Ręczny na żądanie. Wymagany restart.",
            ["regbackup"]="Windows 10 1803+ pomija kopię, gdy jest wyłączone. Restart nie jest wymagany.",
            ["compact-mode"]="Dla użytkownika. Działa po ponownym otwarciu okien Eksploratora.",
            ["long-paths"]="Aplikacje muszą deklarować obsługę longPathAware, aby to zadziałało. Bezpiecznie włączyć. Wymagany restart.",
            ["quickaccess-history"]="Wyłączenie czyści ślad prywatności, ale usuwa też przydatne skróty. Dla użytkownika.",
            ["insider-service"]="Potrzebne tylko w kompilacjach Insider Preview. Wymagany restart.",
            ["sensor-services"]="Włączenie przywraca tryb Ręczny na żądanie. Wyłączenie psuje automatyczną jasność i obrót na tabletach. Wymagany restart.",
            ["search-index"]="Wyłączenie spowalnia wyszukiwanie plików, ale oszczędza zapis na dysku i pracę CPU oraz psuje wyszukiwanie w Start i Outlook, dopóki jest wyłączone. Ponowne włączenie przywraca opóźniony start. Wymagany restart.",
            ["telemetry-services"]="Zatrzymuje DiagTrack, diagnosticshub, dmwappushservice i WdiServiceHost. Narzędzia informacji zwrotnej milczą. Wymagany restart.",
            ["modern-standby"]="Wyłączenie wymusza S3. Najpierw uruchom powercfg /a: na sprzęcie obsługującym tylko S0 uśpienie może zniknąć. Microsoft obsługuje przełączanie tylko przez reinstalację. Wymagany restart.",
            ["hibernation"]="Uruchamia powercfg. Pełny to ustawienie fabryczne, około 40% pamięci RAM; Zmniejszony około 20%; Wyłączono 0%. Zmniejszony i Wyłączono usuwają pozycję Hibernacja z menu. /size 0 działa najpierw, ponieważ powercfg odrzuca zmianę typu, dopóki ustawiony jest własny rozmiar powyżej 40%.", ["rdp-unsigned-warnings"]="Zapisuje RedirectionWarningDialogVersion=1 w HKLM Policies Terminal Services Client oraz RdpLaunchConsentAccepted=1 w HKCU Terminal Server Client. Dotyczy Windows 10 22H2 i Windows 11. UWAGA: wyłącza ostrzeżenie bezpieczeństwa, a Microsoft może usunąć ten mechanizm w przyszłej aktualizacji.", ["widgets-board"]="Dla użytkownika. Nowsze kompilacje Windows 11 mogą go pokazać ponownie; zasada maszynowa znajduje się w Wiadomości i interesy. Efekt natychmiastowy.",
            ["news-interests"]="EnableFeeds to starszy klucz Win10, nieszkodliwy w Win11. Restart nie jest wymagany.",
            ["store-updates"]="Zatrzymuje automatyczne instalacje w stylu Candy Crush na nowych profilach. Sam Store działa dalej. Restart nie jest wymagany.",
            ["telemetry-tasks"]="Wyłącza zadania CEIP, Compatibility Appraiser, Disk Diagnostics i informacji zwrotnych. Zadania synchronizacji czasu, SmartScreen, aktualizacji Store i Historia plików są celowo nietknięte. Brak wskaźnika stanu (sprawdzanie nieobsługiwane).",
            ["cortana"]="AllowCortana nie działa w Windows 11 (Cortana usunięta w 2023); klucze wyszukiwania w sieci nadal tam działają. Wyszukiwanie lokalnych plików działa dalej.",
            ["startmenu-ads"]="Przełączniki ContentDeliveryManager dla użytkownika. Działa natychmiast.",
            ["gamebar"]="Wyłączenie zwalnia zasoby zablokowane przez nagrywanie w tle. Dla użytkownika plus jedna zasada maszynowa.",
            ["gamemode"]="HwSchMode 2 żąda harmonogramowania sprzętowego (WDDM 2.7+); wymuszenie go na starszych GPU może spowodować TDR/BSOD. Zalecany restart.",
            ["ink-workspace"]="Zasady maszynowe plus przełącznik dotyku dla użytkownika. Restart nie jest wymagany.",
            ["spelling-typing"]="Klucze klawiatury dotykowej dla użytkownika (udokumentowane przez społeczność); usunięcie przywraca domyślne. Efekt natychmiastowy.",
            ["cloud-clipboard"]="Lokalne kopiowanie i wklejanie działa dalej; zatrzymują się tylko historia i synchronizacja z chmurą.",
            ["cast-to-device"]="Przełącza wpis bloku rozszerzenia powłoki. Działa natychmiast.",
            ["chrome-debloat"]="Ustawia aktywne zasady Chrome (metryki, informacje zwrotne, niezawodność domen, predykcja, sugestie, tryb tła, GenAI). Działa przy następnym uruchomieniu; pokazuje się jako zarządzane. W pełni odwracalne.",
            ["firefox-debloat"]="Zasady przedsiębiorstwa (telemetria, badania, agent domyślnej przeglądarki, sugestie, FirefoxSuggest, automatyczne wysyłanie awarii) plus wyłączenie zadania Default Browser Agent przez wzorzec nazwy (jego hash się zmienia). Działa przy następnym uruchomieniu; odwracalne. Aktualizacje nigdy nie są naruszane.",
            ["office-debloat"]="Wyłącza cztery zadania agentów telemetrii Office oraz udokumentowane przełączniki OSM, informacji zwrotnych, prywatności i FirstRun (HKCU). Office musi być zamknięty. Dotyczy bieżącego użytkownika; odwracalne.",
            ["nvidia-telemetry"]="Ustawia NvTelemetryContainer Start=4 (nieaktywne, choć usługa pozostaje zarejestrowana) i wyłącza siedem zadań raportowych NvTm* w roota. Nieaktywne bez sterownika NVIDIA; NvContainer/NvDisplay nietknięte. Odwracalne.",
            ["vscode"]="Zapisuje HKCU\\Software\\Policies\\Microsoft\\VSCode: TelemetryLevel off, EnableFeedback 0, UpdateMode manual, DictationLLMCleanup 0. Działa po następnym restarcie. Odwracalne.",
            ["vs-telemetry"]="Udokumentowane wyłączenia SQM plus stary TurnOffSwitch (wewnętrzny, zachowany dla starszych wersji). VSCommon obejmuje 2015-2022 w widoku 64-bitowym. Usługa zbierająca pozostaje nietknięta.",
        
            ["perm-microphone"]="Przełącza wpis CapabilityAccessManager ConsentStore dla dostępu do mikrofonu. Wyłączenie ustawia Value=Deny; włączenie przywraca domyślną zgodę.",
            ["perm-camera"]="Przełącza wpis CapabilityAccessManager ConsentStore dla dostępu do aparatu. Wyłączenie ustawia Value=Deny; włączenie przywraca domyślną zgodę.",
            ["perm-location"]="Przełącza wpis CapabilityAccessManager ConsentStore dla lokalizacji urządzenia. Wyłączenie ustawia Value=Deny; włączenie przywraca domyślną zgodę.",
            ["perm-notifications"]="Przełącza wpis CapabilityAccessManager ConsentStore dla dostępu do powiadomień. Wyłączenie ustawia Value=Deny; włączenie przywraca domyślną zgodę.",
            ["perm-messages"]="Przełącza wpis CapabilityAccessManager ConsentStore dla dostępu do wiadomości. Wyłączenie ustawia Value=Deny; włączenie przywraca domyślną zgodę.",
            ["perm-tasks"]="Przełącza wpis CapabilityAccessManager ConsentStore dla dostępu do zadań. Wyłączenie ustawia Value=Deny; włączenie przywraca domyślną zgodę.",
